insert into lecture_items (id, track_id, position, num, ready, title, description, url) values (8, 1, 7, 8, false, 'Performance Testing AI Features', 'Latency benchmarking, throughput testing, and token-cost optimization. Load testing AI endpoints and establishing performance baselines.', null);
insert into lecture_items (id, track_id, position, num, ready, title, description, url) values (9, 1, 8, 9, false, 'AI-Assisted Test Generation', 'Using AI agents to generate test cases, identify edge cases, and triage failures. GitHub Copilot, Cursor, and custom test-generation pipelines.', null);
insert into lecture_items (id, track_id, position, num, ready, title, description, url) values (10, 1, 9, 10, false, 'Building an AI Testing Strategy', 'Putting it all together — designing a full AI testing strategy for your team, from unit to system level, with metrics, reporting, and continuous improvement.', null);
insert into lecture_tracks (id, lang, position, title, lead) values (2, 'en', 1, 'AI-Powered Basic Cybersecurity', 'Foundational cybersecurity concepts, powered and accelerated by AI tools.');
insert into lecture_items (id, track_id, position, num, ready, title, description, url) values (11, 2, 0, 1, true, 'Introduction to Cybersecurity with AI', 'The fundamentals of cybersecurity — threats, attack surfaces, and defense-in-depth — and how AI tools are reshaping how security teams work today.', 'https://ai--hktwaey.gamma.site/');
insert into lecture_items (id, track_id, position, num, ready, title, description, url) values (12, 2, 1, 2, true, 'AI in Network Security Monitoring', 'Applying AI to traffic analysis and intrusion detection — spotting lateral movement and exfiltration patterns in network logs.', 'https://ml-gf56k78.gamma.site/');
insert into lecture_items (id, track_id, position, num, ready, title, description, url) values (13, 2, 2, 3, false, 'AI-Powered Threat Detection Basics', 'How machine learning models flag suspicious activity, from rule-based detection to anomaly scoring, and where AI adds real value over static rules.', null);
insert into lecture_items (id, track_id, position, num, ready, title, description, url) values (14, 2, 3, 4, false, 'Phishing & Social Engineering Detection with AI', 'Using AI to spot phishing emails, deepfake voice scams, and social engineering attempts before they reach end users.', null);
insert into lecture_items (id, track_id, position, num, ready, title, description, url) values (15, 2, 4, 5, false, 'Malware Analysis Using Machine Learning', 'Classifying and clustering malware samples with ML models, and the basics of static vs. behavioral analysis pipelines.', null);
insert into lecture_items (id, track_id, position, num, ready, title, description, url) values (16, 2, 5, 6, false, 'Automating Vulnerability Scanning with AI', 'How AI-assisted scanners prioritize and triage vulnerabilities, reducing noise and helping teams focus on what matters.', null);
insert into lecture_items (id, track_id, position, num, ready, title, description, url) values (17, 2, 6, 7, false, 'AI for Log Analysis & Anomaly Detection', 'Turning massive log volumes into actionable alerts with AI-driven anomaly detection and clustering techniques.', null);
insert into lecture_items (id, track_id, position, num, ready, title, description, url) values (18, 2, 7, 8, false, 'Securing AI Systems Themselves', 'The flip side — protecting your own AI systems from prompt injection, model theft, data poisoning, and supply-chain risks.', null);
insert into lecture_items (id, track_id, position, num, ready, title, description, url) values (19, 2, 8, 9, false, 'AI-Assisted Incident Response', 'Using AI copilots to speed up triage, root-cause analysis, and reporting during a live security incident.', null);
insert into lecture_items (id, track_id, position, num, ready, title, description, url) values (20, 2, 9, 10, false, 'Building a Cybersecurity AI Strategy', 'Putting it all together — a practical roadmap for adopting AI across detection, response, and prevention in your security program.', null);
insert into lecture_tracks (id, lang, position, title, lead) values (3, 'he', 0, 'בדיקות AI', 'מהיסודות של בדיקות AI ועד לטכניקות הערכה מתקדמות.');